// Secure Express.js application with security best practices

const express = require('express');
const cors = require('cors');
const compression = require('compression');
const morgan = require('morgan');
const dotenv = require('dotenv');

// Load environment variables
if (process.env.NODE_ENV !== 'production') {
  dotenv.config({ path: process.env.ENV_FILE || '.env' });
}

// Security middleware imports
const { 
  limiter, 
  validateRequest, 
  xssProtection, 
  securityHeaders, 
  body, 
  validationResult 
} = require('./security-middleware');

const { authenticateToken, authorize } = require('./auth-middleware');

const app = express();

// Security middleware setup
app.use(securityHeaders);
app.use(xssProtection);
app.use(limiter);
app.use(compression());
app.use(morgan('combined'));
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS ? process.env.ALLOWED_ORIGINS.split(',') : [],
  credentials: true
}));

// Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ extended: true, limit: '10kb' }));

// Health endpoint - public
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: process.env.npm_package_version || '1.0.0'
  });
});

// Protected users endpoint with validation
app.get('/users', 
  authenticateToken,
  authorize(['admin', 'user']),
  [
    body('page').optional().isInt({ min: 1 }).withMessage('Page must be a positive integer'),
    body('limit').optional().isInt({ min: 1, max: 100 }).withMessage('Limit must be between 1 and 100')
  ],
  validateRequest,
  (req, res) => {
    // Mock data - in production, this would come from a secure database
    const users = [
      { 
        id: 1, 
        name: 'Alice', 
        email: 'a***e@example.com', // Masked email for privacy
        role: 'user'
      },
      { 
        id: 2, 
        name: 'Bob', 
        email: 'b**@example.com', // Masked email for privacy
        role: 'admin'
      },
    ];

    // Filter data based on user role
    const filteredUsers = users.map(user => ({
      id: user.id,
      name: user.name,
      email: req.user.role === 'admin' ? user.email : user.email.replace(/[^@]*@/.test(user.email) ? user.email.replace(/(.).*?(.@.*)/, '$1***$2') : user.email),
      role: req.user.role === 'admin' ? user.role : undefined
    }));

    res.json({
      data: filteredUsers,
      pagination: {
        page: parseInt(req.query.page) || 1,
        limit: parseInt(req.query.limit) || 10,
        total: filteredUsers.length
      }
    });
  }
);

// Error handling middleware
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Don't leak error details in production
  if (process.env.NODE_ENV === 'production') {
    return res.status(500).json({ 
      message: 'Internal server error' 
    });
  }

  res.status(500).json({ 
    message: err.message,
    stack: err.stack 
  });
});

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({ 
    message: 'Route not found' 
  });
});

// Graceful shutdown handling
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  process.exit(0);
});

process.on('SIGINT', () => {
  console.log('SIGINT received, shutting down gracefully');
  process.exit(0);
});

const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Secure server running on port ${PORT} in ${process.env.NODE_ENV || 'development'} mode`);
});

module.exports = app;

