const Joi = require('joi');

// Environment variables schema with validation
const envVarsSchema = Joi.object({
  NODE_ENV: Joi.string()
    .valid('development', 'production', 'test')
    .default('development'),
  PORT: Joi.number().default(3000),

  // Database (when implemented)
  DATABASE_URL: Joi.string().uri().optional(),

  // API Keys (when implemented) - mark as required when needed
  AWS_ACCESS_KEY_ID: Joi.string().optional(),
  AWS_SECRET_ACCESS_KEY: Joi.string().optional(),
  ANTHROPIC_API_KEY: Joi.string().optional(),
  STRIPE_SECRET_KEY: Joi.string().optional(),

  // Security
  JWT_SECRET: Joi.string().optional(),
  SESSION_SECRET: Joi.string().optional(),

  // Monitoring
  LOGFIRE_TOKEN: Joi.string().optional(),
})
  .unknown() // Allow unknown vars but don't validate them
  .with('AWS_ACCESS_KEY_ID', 'AWS_SECRET_ACCESS_KEY'); // If one AWS var exists, require both

const { value: envVars, error } = envVarsSchema.validate(process.env);

if (error) {
  throw new Error(`Config validation error: ${error.message}`);
}

const config = {
  env: envVars.NODE_ENV,
  port: envVars.PORT,

  // Database config
  database: {
    url: envVars.DATABASE_URL,
  },

  // AWS config
  aws: {
    accessKeyId: envVars.AWS_ACCESS_KEY_ID,
    secretAccessKey: envVars.AWS_SECRET_ACCESS_KEY,
  },

  // API Keys
  apiKeys: {
    anthropic: envVars.ANTHROPIC_API_KEY,
    stripe: envVars.STRIPE_SECRET_KEY,
  },

  // Security
  jwtSecret: envVars.JWT_SECRET || 'fallback-secret-for-development-only',
  sessionSecret: envVars.SESSION_SECRET || 'fallback-session-secret',

  // Monitoring
  logfireToken: envVars.LOGFIRE_TOKEN,
};

// Security: Mask sensitive values in logs
config.toString = function() {
  const masked = { ...this };
  if (masked.aws.accessKeyId) masked.aws.accessKeyId = '***MASKED***';
  if (masked.aws.secretAccessKey) masked.aws.secretAccessKey = '***MASKED***';
  if (masked.apiKeys.anthropic) masked.apiKeys.anthropic = '***MASKED***';
  if (masked.apiKeys.stripe) masked.apiKeys.stripe = '***MASKED***';
  if (masked.jwtSecret) masked.jwtSecret = '***MASKED***';
  if (masked.sessionSecret) masked.sessionSecret = '***MASKED***';
  return JSON.stringify(masked, null, 2);
};

module.exports = config;

