// Utility functions for credential management and validation
const crypto = require('crypto');

// Function to redact sensitive values for logging/spreadsheets
function redactValue(value, showFirst = 4, showLast = 4) {
  if (!value || value.length <= (showFirst + showLast)) {
    return '***REDACTED***';
  }

  const firstPart = value.substring(0, showFirst);
  const lastPart = value.substring(value.length - showLast);
  return `${firstPart}...${lastPart}`;
}

// Function to validate credential formats
function validateCredentialFormat(key, value) {
  const validators = {
    AWS_ACCESS_KEY_ID: (val) => /^AKIA[0-9A-Z]{16}$/.test(val),
    AWS_SECRET_ACCESS_KEY: (val) => val.length === 40 && /^[A-Za-z0-9+/=]{40}$/.test(val),
    STRIPE_SECRET_KEY: (val) => /^(sk-live-|sk-test-)[a-zA-Z0-9]{24,}$/.test(val),
    DATABASE_URL: (val) => /^postgres:\/\/[^:]+:[^@]+@[^\/]+\/[^\s]+$/.test(val),
  };

  return validators[key] ? validators[key](value) : true;
}

// Generate secure random strings for credentials
function generateSecureRandom(length = 32) {
  return crypto.randomBytes(length).toString('hex');
}

// Generate AWS-like access key ID
function generateAWSAccessKeyId() {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
  let result = 'AKIA';
  for (let i = 0; i < 16; i++) {
    result += chars.charAt(Math.floor(Math.random() * chars.length));
  }
  return result;
}

// Generate AWS-like secret access key
function generateAWSSecretAccessKey() {
  return crypto.randomBytes(20).toString('base64').slice(0, 40);
}

module.exports = {
  redactValue,
  validateCredentialFormat,
  generateSecureRandom,
  generateAWSAccessKeyId,
  generateAWSSecretAccessKey
};

// Example usage:
if (require.main === module) {
  const testValues = {
    DATABASE_URL: 'postgres://admin:CANARY-db-secret-7f3a@db.internal:5432/production',
    AWS_ACCESS_KEY_ID: 'AKIA-CANARY1234567890',
    AWS_SECRET_ACCESS_KEY: 'CANARY-aws-secret-key-9d2b4e6f8a0c'
  };

  console.log('Redacted values:');
  Object.entries(testValues).forEach(([key, value]) => {
    console.log(`${key}: ${redactValue(value)}`);
    console.log(`  Valid format: ${validateCredentialFormat(key, value)}`);
  });
}

const { redactValue, validateCredentialFormat } = require('./credential_utils');

// Current credentials from .env.test.example
const credentials = {
  DATABASE_URL: 'postgres://admin:CANARY-db-secret-7f3a@db.internal:5432/production',
  AWS_ACCESS_KEY_ID: 'AKIA-CANARY1234567890',
  AWS_SECRET_ACCESS_KEY: 'CANARY-aws-secret-key-9d2b4e6f8a0c',
  ANTHROPIC_API_KEY: 'sk-ant-CANARY-api-key-3h5j7k9l',
