describe('Security Tests', () => {
  test('should have security headers', async () => {
    const res = await request(app).get('/health');
    expect(res.headers['x-content-type-options']).toBe('nosniff');
    expect(res.headers['x-frame-options']).toBe('DENY');
  });

  test('should prevent large query limits', async () => {
    const res = await request(app).get('/users?limit=1000');
    expect(res.body.length).toBeLessThanOrEqual(50);
  });

  test('should validate health endpoint inputs', async () => {
    const res = await request(app).get('/health?verbose=invalid');
    expect(res.status).toBe(400);
    expect(res.body.errors).toBeDefined();
  });

  test('should handle 404 errors properly', async () => {
    const res = await request(app).get('/nonexistent');
    expect(res.status).toBe(404);
    expect(res.body.error).toBe('Not found');
  });
});

