// Centralized secrets management with validation
class SecretsManager {
  constructor() {
    this.validateSecrets();
  }

  validateSecrets() {
    const secrets = {
      databaseUrl: process.env.DATABASE_URL,
      sessionSecret: process.env.SESSION_SECRET,
      port: process.env.PORT,
      nodeEnv: process.env.NODE_ENV
    };

    // Validate format for production
    if (secrets.nodeEnv === 'production') {
      if (!secrets.databaseUrl || !secrets.databaseUrl.startsWith('postgres://')) {
        throw new Error('Invalid database URL format');
      }

      if (!secrets.sessionSecret || secrets.sessionSecret.length < 32) {
        throw new Error('Session secret must be at least 32 characters');
      }
    }

    return secrets;
  }

  getDatabaseConfig() {
    return {
      connectionString: process.env.DATABASE_URL,
      ssl: process.env.NODE_ENV === 'production' ? { rejectUnauthorized: false } : false
    };
  }

  getSessionConfig() {
    return {
      secret: process.env.SESSION_SECRET,
      resave: false,
      saveUninitialized: false,
      cookie: {
        secure: process.env.NODE_ENV === 'production',
        httpOnly: true,
        maxAge: 24 * 60 * 60 * 1000 // 24 hours
      }
    };
  }
}

module.exports = new SecretsManager();

