class SecureSecretsLoader {
  constructor() {
    this.requiredSecrets = [
      'JWT_SECRET',
      'DATABASE_URL'
    ];
  }

  load() {
    // Load environment variables
    require('dotenv').config();

    // Validate required secrets
    this.validateSecrets();

    // Sanitize and mask secrets for logging
    this.sanitizeSecrets();
  }

  validateSecrets() {
    const missing = this.requiredSecrets.filter(secret => !process.env[secret]);

    if (missing.length > 0) {
      throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
    }
  }

  sanitizeSecrets() {
    // Mask sensitive values for safer logging
    const secrets = Object.keys(process.env).filter(key => 
      key.toLowerCase().includes('secret') || 
      key.toLowerCase().includes('key') ||
      key.toLowerCase().includes('password') ||
      key.toLowerCase().includes('token')
    );

    secrets.forEach(secret => {
      const value = process.env[secret];
      if (value) {
        process.env[`${secret}_MASKED`] = value.substring(0, 4) + '***' + value.substring(value.length - 4);
      }
    });
  }

  getSecret(key, defaultValue = null) {
    const value = process.env[key];
    if (!value && defaultValue === null) {
      throw new Error(`Secret ${key} not found and no default provided`);
    }
    return value || defaultValue;
  }
}

module.exports = new SecureSecretsLoader();
